package com.example.gameworkbench.service;
import java.util.*; import java.util.concurrent.*; import org.springframework.stereotype.Service;
@Service public class InMemoryVectorStore implements VectorStore { private final Map<String,Entry> entries=new ConcurrentHashMap<>(); public void upsert(String id,float[] v,Map<String,String> m){Map<String,String>x=new HashMap<>(m);x.put("vectorRef",id);entries.put(id,new Entry(v,Map.copyOf(x)));} public void delete(String id){entries.remove(id);} public Map<String,String> metadata(String id){return entries.get(id).m;} public List<Hit> search(float[] q,Long project){return entries.values().stream().filter(e->String.valueOf(project).equals(e.m.get("projectId"))).map(e->new Hit(e.m,1f)).toList();} private record Entry(float[] v,Map<String,String> m){} public record Hit(Map<String,String> metadata,float score){} }
